"""Generate tests/pml_reference.rs from pytorch-metric-learning.

Each case evaluates one loss on a fixed batch in float64 and records the loss
and its autograd gradients. Run from the repository root:

    uv run --with torch==2.15.0 --with pytorch-metric-learning==3.0.1 \
        python tests/fixtures/gen_pml_reference.py > tests/pml_reference.rs
"""

import importlib.metadata
import torch
from pytorch_metric_learning import losses

PML_VERSION = importlib.metadata.version("pytorch-metric-learning")
N, D, C = 8, 4, 3


def lcg(seed):
    s = seed
    while True:
        s = (s * 6364136223846793005 + 1442695040888963407) % 2**64
        yield ((s >> 33) / 2**31) * 2.0 - 1.0


gen = lcg(11)
EMB = [[next(gen) for _ in range(D)] for _ in range(N)]
LABELS = [0, 0, 1, 1, 2, 2, 0, 1]
PROXIES = [[next(gen) for _ in range(D)] for _ in range(C)]


def f32(x):
    target = torch.tensor(x, dtype=torch.float32)
    for digits in range(1, 10):
        text = f"{float(target):.{digits}g}"
        if torch.tensor(float(text), dtype=torch.float32) == target:
            break
    return text if ("e" in text or "." in text) else text + ".0"


def rows(m, indent):
    return "\n".join(indent + "[" + ", ".join(f32(x) for x in r) + "]," for r in m)


def run(make, with_proxies):
    e = torch.tensor(EMB, dtype=torch.float64, requires_grad=True)
    loss_fn = make()
    p = None
    if with_proxies:
        loss_fn.weight.data = torch.tensor(PROXIES, dtype=torch.float64)
        p = loss_fn.weight
    loss = loss_fn(e, torch.tensor(LABELS))
    loss.backward()
    grad_p = None
    if p is not None:
        grad_p = p.grad
    return float(loss.detach()), e.grad.tolist(), None if grad_p is None else grad_p.tolist()


# (name, tuplet call, pml constructor, whether the loss has class proxies)
CASES = [
    ("multi_similarity", "multi_similarity_loss(&emb, &LABELS, 2.0, 50.0, 0.5)",
     lambda: losses.MultiSimilarityLoss(alpha=2, beta=50, base=0.5), False),
    ("supcon", "supcon_loss(&emb, &LABELS, 0.1)",
     lambda: losses.SupConLoss(temperature=0.1), False),
    # Value only: pml detaches the alpha weights (as the paper's gradient
    # specifies), while tuplet's f32 circle_loss returns the exact gradient of
    # the loss as written, so the gradients differ by design.
    ("circle", "circle_loss(&emb, &LABELS, 0.25, 32.0)",
     lambda: losses.CircleLoss(margin=0.25, gamma=32), False),
    ("proxy_anchor", "proxy_anchor_loss(&emb, &LABELS, &proxies, 0.1, 32.0)",
     lambda: losses.ProxyAnchorLoss(num_classes=C, embedding_size=D, margin=0.1, alpha=32), True),
    ("arcface", "arcface_loss(&emb, &LABELS, &proxies, 16.0, 0.5)",
     lambda: losses.ArcFaceLoss(num_classes=C, embedding_size=D, margin=0.5, scale=16), True),
]

print(f"""//! Loss values and gradients against pytorch-metric-learning {PML_VERSION}.
//!
//! Generated by `tests/fixtures/gen_pml_reference.py`; do not edit by hand.
//! The reference runs in float64 with autograd; tuplet computes hand-derived
//! gradients in f32. Hyperparameters are set explicitly on both sides.

use tuplet::*;

const EMB: [[f32; {D}]; {N}] = [
{rows(EMB, "    ")}
];

const LABELS: [usize; {N}] = {LABELS};

const PROXIES: [[f32; {D}]; {C}] = [
{rows(PROXIES, "    ")}
];

fn close(got: f32, want: f32) -> bool {{
    (got - want).abs() <= 1e-4 * want.abs().max(1.0)
}}

fn check(name: &str, out: LossOutput, loss: f32, grad_emb: &[[f32; {D}]], grad_proxies: &[[f32; {D}]]) {{
    assert!(close(out.loss, loss), "{{name}} loss: tuplet {{}}, pml {{loss}}", out.loss);
    for (what, got, want) in [
        ("embedding", &out.grad_anchors, grad_emb),
        ("proxy", &out.grad_positives, grad_proxies),
    ] {{
        if want.is_empty() {{
            continue;
        }}
        assert_eq!(got.len(), want.len(), "{{name}} {{what}} gradient count");
        for (i, (g, w)) in got.iter().zip(want).enumerate() {{
            for (d, (g, w)) in g.iter().zip(w).enumerate() {{
                assert!(close(*g, *w), "{{name}} {{what}} grad [{{i}}][{{d}}]: tuplet {{g}}, pml {{w}}");
            }}
        }}
    }}
}}""")

for name, call, make, proxy in CASES:
    loss, ge, gp = run(make, proxy)
    if name == "circle":
        ge = []
    gp_rows = f"[\n{rows(gp, '            ')}\n        ]" if gp is not None else "[]"
    doc = ("\n/// Loss value only: pml detaches the alpha weights, as the paper's gradient\n"
           "/// specifies; tuplet's f32 circle_loss returns the exact gradient.") if name == "circle" else ""
    print(f"""{doc}
#[test]
fn {name}_matches_pml() {{
    let emb: Vec<&[f32]> = EMB.iter().map(|v| v.as_slice()).collect();
    #[allow(unused_variables)]
    let proxies: Vec<&[f32]> = PROXIES.iter().map(|v| v.as_slice()).collect();
    check(
        "{name}",
        {call},
        {f32(loss)},
        &[
{rows(ge, "            ")}
        ],
        &{gp_rows},
    );
}}""")
